<script setup lang="ts">
const props = withDefaults(defineProps<{ task?: { title: string; body?: string; genre: string; version: number } }>(), { task: undefined })
const form = reactive({ title: props.task?.title ?? '', body: props.task?.body ?? '', genre: props.task?.genre ?? '', parent: '', taskType: '', priority: '', start: '', end: '' })
const warning = ref(false)
function submit() { if (form.parent || (form.start && form.end)) warning.value = true }
</script>
<template><form class="card form" @submit.prevent="submit"><label>タイトル<span aria-hidden="true"> *</span><input v-model="form.title" required /></label><label>本文<textarea v-model="form.body" /></label><label>ジャンル<select v-model="form.genre" required><option value="">選択してください</option><option>開発</option><option>運用</option></select></label><div class="form-grid"><label>親タスク<select v-model="form.parent"><option value="">Root</option><option>認証基盤</option></select></label><label>タスクタイプ<select v-model="form.taskType"><option value="">指定なし</option><option>実装</option></select></label><label>優先度<select v-model="form.priority"><option value="">自動</option><option>HIGH</option><option>MEDIUM</option><option>LOW</option></select></label><label>開始<input v-model="form.start" type="datetime-local" /></label><label>期限<input v-model="form.end" type="datetime-local" /></label></div><button class="primary" type="submit">{{ task ? '変更を保存' : 'タスクを作成' }}</button><ImpactModal :open="warning" title="変更の確認" :impacts="['Hierarchy・日付への影響をサーバーで再確認します']" @cancel="warning=false" @confirm="warning=false" /></form></template>
